hod\nAutomated timesheet approvals,Liza Martines,Digital core,Internal process,Q4 2024,Q2 2025,90,On track,Cut approval time from five days to one\nGraduate academy,Amara Singh,People and skills,Learning and growth,Q2 2025,Q1 2026,240,Planned,A twelve-month programme for 20 graduates a year\nBenelux office,Paul Reyes,Growth,Financial,Q3 2026,Q1 2026,400,Planned,Ends before it starts\n","sort":2,"extra":null},{"id":"kpis","file_name":"measures-sample.csv","content":"Measure,Period,Value,Comment\nK01,Sep 2024,44,Two renewals signed early\nOperating margin,Sep 2024,15.1,Lower subcontractor costs\nNew clients in new markets,Sep 2024,12,\nClient happiness,Sep 2024,8.4,Not a measure in OrgCue\nK05,Sep 2024,about 90,\n","sort":3,"extra":null}]$rsaod9r$::jsonb);
delete from public."product_panel_findings" where workspace_id = '00000000-0000-4000-8000-000000000002';
insert into public."product_panel_findings" (workspace_id, "id", "sort", "text", "extra")
select '00000000-0000-4000-8000-000000000002', "id", "sort", "text", "extra" from jsonb_populate_recordset(null::public."product_panel_findings", $romvdp8$[{"id":"A1","text":"The thread from objective to measure, initiative and task, with gap coverage, is rare and worth leading with.","sort":0,"extra":null},{"id":"A2","text":"The biggest weakness was consistency: the same initiative had different dates, budgets and statuses on different pages. This release makes the initiative the master record for projects, spend and the review pack.","sort":1,"extra":null},{"id":"A3","text":"Strategy needs a running system, not only views: calculated status, dated check-ins, OKR confidence and a decision log. All four shipped in this release.","sort":2,"extra":null},{"id":"A4","text":"Next comes real multi-user data, permissions and budgets by month. Without them OrgCue stays a demo.","sort":3,"extra":null},{"id":"A5","text":"Position OrgCue as the strategy-to-delivery layer above Asana, monday.com and Jira, and integrate with them rather than compete on tasks.","sort":4,"extra":null}]$romvdp8$::jsonb);
delete from public."product_panel_lists" where workspace_id = '00000000-0000-4000-8000-000000000002';
insert into public."product_panel_lists" (workspace_id, "id", "sort", "person_id", "kind", "text", "extra")
select '00000000-0000-4000-8000-000000000002', "id", "sort", "person_id", "kind", "text", "extra" from jsonb_populate_recordset(null::public."product_panel_lists", $rqqijwk$[{"id":"SC:good:1","sort":0,"person_id":"SC","kind":"good","text":"Target coverage on the initiative portfolio","extra":null},{"id":"SC:good:2","sort":1,"person_id":"SC","kind":"good","text":"The exceptions-first strategy review","extra":null},{"id":"SC:good:3","sort":2,"person_id":"SC","kind":"good","text":"The initiative page and ambition tracker","extra":null},{"id":"SC:gaps:1","sort":3,"person_id":"SC","kind":"gaps","text":"Status typed by hand; no dated history","extra":null},{"id":"SC:gaps:2","sort":4,"person_id":"SC","kind":"gaps","text":"OKRs without check-ins or confidence","extra":null},{"id":"SC:gaps:3","sort":5,"person_id":"SC","kind":"gaps","text":"No decision or action log","extra":null},{"id":"SC:gaps:4","sort":6,"person_id":"SC","kind":"gaps","text":"No real cascade to business units","extra":null},{"id":"SC:gaps:5","sort":7,"person_id":"SC","kind":"gaps","text":"No strategic risks or scenarios","extra":null},{"id":"PD:good:1","sort":11,"person_id":"PD","kind":"good","text":"Four health signals with baselines","extra":null},{"id":"PD:good:2","sort":12,"person_id":"PD","kind":"good","text":"Initiatives linked to KPIs with expected impact","extra":null},{"id":"PD:good:3","sort":13,"person_id":"PD","kind":"good","text":"Structured status updates with staleness","extra":null},{"id":"PD:good:4","sort":14,"person_id":"PD","kind":"good","text":"The task panel is as good as Asana's","extra":null},{"id":"PD:gaps:1","sort":15,"person_id":"PD","kind":"gaps","text":"Projects and initiatives kept separate records","extra":null},{"id":"PD:gaps:2","sort":16,"person_id":"PD","kind":"gaps","text":"No intake or business case","extra":null},{"id":"PD:gaps:3","sort":17,"person_id":"PD","kind":"gaps","text":"Gates with one question and no criteria","extra":null},{"id":"PD:gaps:4","sort":18,"person_id":"PD","kind":"gaps","text":"No monthly budgets or capex and opex view","extra":null},{"id":"PD:gaps:5","sort":19,"person_id":"PD","kind":"gaps","text":"No capacity by role or change control","extra":null},{"id":"SF:good:1","sort":23,"person_id":"SF","kind":"good","text":"One line from the board to this week's tasks","extra":null},{"id":"SF:good:2","sort":24,"person_id":"SF","kind":"good","text":"The review pack is a sharp wedge","extra":null},{"id":"SF:good:3","sort":25,"person_id":"SF","kind":"good","text":"Portfolio control looks credible","extra":null},{"id":"SF:gaps:1","sort":26,"person_id":"SF","kind":"gaps","text":"No real multi-user back end","extra":null},{"id":"SF:gaps:2","sort":27,"person_id":"SF","kind":"gaps","text":"No first-run experience","extra":null},{"id":"SF:gaps:3","sort":28,"person_id":"SF","kind":"gaps","text":"Three areas that model the same thing twice","extra":null},{"id":"SF:gaps:4","sort":29,"person_id":"SF","kind":"gaps","text":"An AI assistant that did not use the data","extra":null},{"id":"SF:gaps:5","sort":30,"person_id":"SF","kind":"gaps","text":"No integrations, permissions or SSO","extra":null},{"id":"MA:good:1","sort":34,"person_id":"MA","kind":"good","text":"Hoshin and benefits tracking are rare differentiators","extra":null},{"id":"MA:good:2","sort":35,"person_id":"MA","kind":"good","text":"Strategy, portfolio and work in one product matches where the market is going","extra":null},{"id":"MA:gaps:1","sort":36,"person_id":"MA","kind":"gaps","text":"AI agents are now table stakes","extra":null},{"id":"MA:gaps:2","sort":37,"person_id":"MA","kind":"gaps","text":"Integrations and an API or MCP server are expected","extra":null},{"id":"MA:gaps:3","sort":38,"person_id":"MA","kind":"gaps","text":"Enterprise trust features are expected","extra":null}]$rqqijwk$::jsonb);
