insert into public."product_panel_people" (workspace_id, "id", "sort", "role", "color", "lens", "quote", "extra")
select '00000000-0000-4000-8000-000000000002', "id", "sort", "role", "color", "lens", "quote", "extra" from jsonb_populate_recordset(null::public."product_panel_people", $r2pipjr$[{"id":"SC","sort":0,"role":"Strategy consultant","color":"#6a2bc4","lens":"Strategy formulation and execution with executive teams","quote":"The views are good; what was missing is the system that runs strategy month after month.","extra":null},{"id":"PD","sort":1,"role":"PMO director","color":"#2f6fd8","lens":"Enterprise PMOs and transformation offices","quote":"Governance is what a PMO buys PPM for. Make every number come from one record.","extra":null},{"id":"SF","sort":2,"role":"SaaS founder","color":"#17946a","lens":"Built and scaled two collaboration SaaS companies","quote":"Sell the quarterly review pack that writes itself, to the COO and the strategy office, and sit above Asana and Jira.","extra":null},{"id":"MA","sort":3,"role":"Market analyst","color":"#c77a0a","lens":"Researched more than 40 vendors across the three markets","quote":"Large vendors are converging strategy, portfolio and work by acquisition. OrgCue has it in one model; now it needs the platform.","extra":null}]$r2pipjr$::jsonb);
