insert into public."product_roadmap_areas" (workspace_id, "id", "sort", "color", "extra")
select '00000000-0000-4000-8000-000000000002', "id", "sort", "color", "extra" from jsonb_populate_recordset(null::public."product_roadmap_areas", $r33eous$[{"id":"Strategy","color":"#6a2bc4","sort":0,"extra":null},{"id":"Portfolio","color":"#2f6fd8","sort":1,"extra":null},{"id":"Work","color":"#17946a","sort":2,"extra":null},{"id":"Collaboration","color":"#c2409f","sort":3,"extra":null},{"id":"Reporting","color":"#c77a0a","sort":4,"extra":null},{"id":"AI","color":"#e255c9","sort":5,"extra":null},{"id":"Platform","color":"#5b6577","sort":6,"extra":null},{"id":"Integrations","color":"#3b6fe0","sort":7,"extra":null}]$r33eous$::jsonb);
