select '00000000-0000-4000-8000-000000000002', "id", "sort", "name", "description", "extra" from jsonb_populate_recordset(null::public."product_roadmap_horizons", $r88rg7m$[{"id":"done","name":"Shipped","description":"Live in OrgCue","sort":0,"extra":null},{"id":"now","name":"Now","description":"This quarter","sort":1,"extra":null},{"id":"next","name":"Next","description":"Next one to two quarters","sort":2,"extra":null},{"id":"later","name":"Later","description":"Later this year and beyond","sort":3,"extra":null}]$r88rg7m$::jsonb);
