insert into public."product_roadmap_items" (workspace_id, "id", "sort", "title", "area", "horizon", "status", "go", "votes", "asked_by", "refs", "why", "what", "collab", "extra")
select '00000000-0000-4000-8000-000000000002', "id", "sort", "title", "area", "horizon", "status", "go", "votes", "asked_by", "refs", "why", "what", "collab", "extra" from jsonb_populate_recordset(null::public."product_roadmap_items", $ribgcog$[{"id":"RM1","sort":0,"title":"Measures with calculated status and dated check-ins","area":"Strategy","horizon":"done","status":"Shipped","go":"st-kpis","votes":14,"asked_by":["S"],"refs":["Cascade","ClearPoint","Spider Impact"],"why":"Status was typed by hand, so the same number got different verdicts on different pages.","what":"Status follows progress against the plan, with tolerance bands; owners can override with a reason. Each check-in has a period, comment and history.","collab":null,"extra":null},{"id":"RM2","sort":1,"title":"OKR check-ins with confidence","area":"Strategy","horizon":"done","status":"Shipped","go":"st-okr","votes":11,"asked_by":["S"],"refs":["WorkBoard","Perdoo","Profit.co"],"why":"OKRs were static; leaders need a weekly signal of confidence, not just progress.","what":"Click a key result to record its value, your confidence and a note.","collab":null,"extra":null},{"id":"RM3","sort":2,"title":"Decision and action log","area":"Reporting","horizon":"done","status":"Shipped","go":"wk-decisions","votes":16,"asked_by":["S","P"],"refs":["WorkBoard","Planview","ClearPoint"],"why":"Steering decisions were fixed text, and nothing carried over to the next review.","what":"Record decisions with rationale, create follow-up actions, and see open actions in the strategy review. Stage gates and requests log their decisions too.","collab":null,"extra":null},{"id":"RM4","sort":3,"title":"Requests: demand intake with scoring","area":"Portfolio","horizon":"done","status":"Shipped","go":"wk-intake","votes":13,"asked_by":["P"],"refs":["ServiceNow SPM","Planview","monday.com"],"why":"New ideas had no front door, so prioritisation could not see what was coming.","what":"Submit a request, score it on value, strategic fit, ease and risk, then accept it into the portfolio or reject it with a reason.","collab":null,"extra":null},{"id":"RM5","sort":4,"title":"One initiative record, first step","area":"Platform","horizon":"done","status":"Shipped","go":"dashboard","votes":12,"asked_by":["P","F"],"refs":["Planview","Smartsheet"],"why":"Project cards, the steering pack and Work showed different dates, budgets and stages for the same work.","what":"Project cards, spend, the review pack and prioritisation now read the initiative. Running work is shown as committed.","collab":null,"extra":null},{"id":"RM6","sort":5,"title":"Assistant that answers from live data","area":"AI","horizon":"done","status":"Shipped","go":null,"votes":15,"asked_by":["F"],"refs":["Linear","Asana","WorkBoard"],"why":"The demo assistant searched file names; asked what was off track, it returned a meeting.","what":"Ask what is off track, where money is at risk, whose updates are overdue or for a steering brief, and get a draft status update for any initiative.","collab":null,"extra":null},{"id":"RM7","sort":6,"title":"Guided first run and tours","area":"Platform","horizon":"done","status":"Shipped","go":"dashboard","votes":8,"asked_by":["F"],"refs":["Asana","monday.com"],"why":"First-time visitors landed on a project dashboard with no idea where to start.","what":"Pick your role on the welcome card and follow a five-step tour; both tours are in Help.","collab":null,"extra":null},{"id":"RM8","sort":7,"title":"Real accounts and shared data","area":"Platform","horizon":"done","status":"Shipped","go":"settings-pl-workspace","votes":21,"asked_by":["F"],"refs":["All leaders"],"why":"Everything lives in one browser today, so no team can use it together.","what":"Sign in, create a shared workspace from the demo, invite people by email and see each other's changes live. Data is stored in Supabase in the EU (Paris).","collab":null,"extra":null},{"id":"RM9","sort":8,"title":"Roles and permissions","area":"Platform","horizon":"done","status":"Shipped","go":"settings-pl-workspace","votes":12,"asked_by":["F","P"],"refs":["Asana","Planview","monday.com"],"why":"Board members, PMO and teams need different rights over targets, budgets and tasks.","what":"Admin, Editor, Contributor and Viewer. Every change is checked against your role; in the demo you can view the app as any role.","collab":null,"extra":null},{"id":"RM10","sort":9,"title":"Monthly budgets, actuals and forecast","area":"Portfolio","horizon":"done","status":"Shipped","go":"budgets","votes":15,"asked_by":["P"],"refs":["Broadcom Clarity","Planview","Asana"],"why":"The first thing a CFO checks: phased budget, actuals, forecast, capex and opex, approved against committed.","what":"Budget, actuals and forecast by month for every initiative, capex and opex, approved against committed, and a portfolio view by month.","collab":null,"extra":null},{"id":"RM11","sort":10,"title":"One task list: fold project plans into initiatives","area":"Work","horizon":"done","status":"Shipped","go":"wk-tasks","votes":13,"asked_by":["P","F"],"refs":["Asana","Smartsheet"],"why":"Projects and Work still keep separate task lists for the same initiatives.","what":"Project plans and initiatives now share one task list, so every view shows the same tasks.","collab":null,"extra":null},{"id":"RM12","sort":11,"title":"Business unit scorecards and a real cascade","area":"Strategy","horizon":"done","status":"Shipped","go":"st-units","votes":11,"asked_by":["S"],"refs":["WorkBoard","Cascade","Spider Impact"],"why":"Units should own targets linked to company objectives, not just a heat map.","what":"Each business unit has its own objectives and measures that roll up to company objectives, with a cascade view.","collab":null,"extra":null},{"id":"RM13","sort":12,"title":"Gate criteria and named approvers","area":"Portfolio","horizon":"done","status":"Shipped","go":"wk-portfolio","votes":9,"asked_by":["P"],"refs":["Planisware","Planview","Wrike"],"why":"Each gate needs a checklist, required approvers and an any/all rule.","what":"Each gate has criteria, named approvers and an any or all rule; approval moves the initiative and logs the decision.","collab":null,"extra":null},{"id":"RM14","sort":13,"title":"Capacity by role and what-if scenarios","area":"Portfolio","horizon":"done","status":"Shipped","go":"wk-capacity","votes":12,"asked_by":["P"],"refs":["Tempus Resource","Planview","Smartsheet"],"why":"Funding choices need demand against capacity by role, without changing the live plan.","what":"Demand against capacity by role and quarter, with drill-down, and what-if scenarios to test the plan.","collab":null,"extra":null},{"id":"RM15","sort":14,"title":"KPI data connectors","area":"Integrations","horizon":"next","status":"Planned","go":null,"votes":10,"asked_by":["S"],"refs":["Profit.co","Cascade","Perdoo"],"why":"Measures should update from finance, CRM and BI, not by hand.","what":null,"collab":null,"extra":null},{"id":"RM16","sort":15,"title":"Slack and Microsoft Teams","area":"Integrations","horizon":"now","status":"Planned","go":null,"votes":11,"asked_by":["F"],"refs":["WorkBoard","Asana","Linear"],"why":"Check-ins, mentions and approvals where people already work.","what":null,"collab":null,"extra":null},{"id":"RM17","sort":16,"title":"Two-way sync with Jira and Azure DevOps","area":"Integrations","horizon":"next","status":"Planned","go":null,"votes":9,"asked_by":["F"],"refs":["monday.com","Planview","Jira Align"],"why":"OrgCue sits above delivery tools; teams keep their tools, leaders see the thread.","what":null,"collab":null,"extra":null},{"id":"RM18","sort":17,"title":"Frozen board packs and export","area":"Reporting","horizon":"done","status":"Shipped","go":"st-review","votes":10,"asked_by":["S"],"refs":["ClearPoint","Cascade","WorkBoard"],"why":"The review pack should go out as PowerPoint or PDF, frozen for each period.","what":"Freeze the review pack each quarter, compare it with live data, and export it as PDF, HTML or CSV.","collab":null,"extra":null},{"id":"RM19","sort":18,"title":"Custom fields and saved views","area":"Work","horizon":"done","status":"Shipped","go":"wk-tasks","votes":8,"asked_by":[],"refs":["Asana","ClickUp","Linear"],"why":"Table stakes in work management; every team tracks something extra.","what":"Add your own task fields and save the views you use, for yourself or the team.","collab":null,"extra":null},{"id":"RM20","sort":19,"title":"Strategic risks and risk appetite","area":"Strategy","horizon":"done","status":"Shipped","go":"st-risks","votes":7,"asked_by":["S"],"refs":["Cascade","ClearPoint"],"why":"The review's top risks are project risks; boards want strategic risks against an appetite.","what":"A strategic risk register with appetite by category, a 5 by 5 heat grid, and mitigations; the review shows risks above appetite.","collab":null,"extra":null},{"id":"RM21","sort":20,"title":"Single sign-on and SCIM","area":"Platform","horizon":"now","status":"Planned","go":null,"votes":9,"asked_by":["F"],"refs":["Asana","Linear","Atlassian"],"why":"Enterprise sign-in through the customer's identity provider, and automatic user provisioning.","what":null,"collab":null,"extra":null},{"id":"RM22","sort":21,"title":"Import from Excel, CSV and Jira files","area":"Platform","horizon":"done","status":"Shipped","go":"settings-pl-import","votes":8,"asked_by":["F"],"refs":["monday.com","Smartsheet"],"why":"Most strategies and portfolios start life in spreadsheets.","what":"Import tasks, initiatives or measure values from a CSV file, Excel paste or a Jira CSV export, with column mapping, preview and undo.","collab":null,"extra":null},{"id":"RM23","sort":22,"title":"Change requests and re-baselining","area":"Portfolio","horizon":"done","status":"Shipped","go":"wk-portfolio","votes":6,"asked_by":["P"],"refs":["Microsoft Planner","Planisware","Celoxis"],"why":"Scope, date and budget changes need approval and a new baseline with history.","what":"Request a change to scope, date or budget; approval re-baselines the initiative and keeps the baseline history.","collab":null,"extra":null},{"id":"RM24","sort":23,"title":"AI agents that chase updates and prepare reviews","area":"AI","horizon":"later","status":"Exploring","go":null,"votes":10,"asked_by":[],"refs":["WorkBoard","Asana","Planview"],"why":"Leaders expect agents to nudge owners, flag drift and assemble the pack, within the user's permissions.","what":null,"collab":null,"extra":null},{"id":"RM25","sort":24,"title":"Public API, webhooks and an MCP server","area":"Integrations","horizon":"later","status":"Exploring","go":null,"votes":7,"asked_by":[],"refs":["Linear","Asana","Atlassian"],"why":"Lets customers and outside AI agents read and update OrgCue safely.","what":null,"collab":null,"extra":null},{"id":"RM26","sort":25,"title":"Strategy scenarios","area":"Strategy","horizon":"done","status":"Shipped","go":"wk-scenarios","votes":6,"asked_by":["S"],"refs":["Planview","Jibility"],"why":"Compare strategic options and their effect on targets before committing.","what":"Compare scenarios side by side: spend against caps, capacity by role and 2026 target coverage.","collab":null,"extra":null},{"id":"RM27","sort":26,"title":"Benefit profiles and realisation tracking","area":"Portfolio","horizon":"done","status":"Shipped","go":"benefits","votes":6,"asked_by":["P"],"refs":["Shibumi","Broadcom Clarity"],"why":"Few tools do this well; it can set OrgCue apart.","what":"Benefits with owners, planned and realised value by quarter, and a portfolio realisation view.","collab":null,"extra":null},{"id":"RM28","sort":27,"title":"Timesheets","area":"Work","horizon":"done","status":"Shipped","go":"wk-time","votes":4,"asked_by":["P"],"refs":["Planview","Clarity","Teamwork.com"],"why":"Needed for actual effort against capacity, mainly in services firms.","what":"Weekly timesheets with submit and approval; hours roll into tasks, initiatives and workload.","collab":null,"extra":null},{"id":"RM29","sort":28,"title":"Phone apps","area":"Platform","horizon":"later","status":"Exploring","go":null,"votes":5,"asked_by":[],"refs":["Asana","WorkBoard"],"why":"Check-ins and approvals on the go.","what":null,"collab":null,"extra":null},{"id":"RM30","sort":29,"title":"Power BI and Tableau connector","area":"Reporting","horizon":"later","status":"Exploring","go":null,"votes":6,"asked_by":[],"refs":["WorkBoard","Planview","Smartsheet"],"why":"Finance and the PMO want the data in their BI tool.","what":null,"collab":null,"extra":null},{"id":"RM31","sort":30,"title":"Critical path and cross-project impact","area":"Portfolio","horizon":"done","status":"Shipped","go":"wk-portfolio","votes":5,"asked_by":["P"],"refs":["Microsoft Planner","Smartsheet","Wrike"],"why":"Show which slips move the end date and which programmes they hit.","what":"The timeline shows the critical chain, and a what-if tool shows what moves when an initiative slips.","collab":null,"extra":null},{"id":"RM32","sort":31,"title":"Governance calendar and meeting cadence","area":"Strategy","horizon":"done","status":"Shipped","go":"st-calendar","votes":5,"asked_by":["S"],"refs":["WorkBoard","ClearPoint"],"why":"Tie reviews, check-in deadlines and period locks to one calendar.","what":"Reviews, board meetings, check-in deadlines and meetings in one calendar, with cadence settings and period locks.","collab":null,"extra":null},{"id":"RM33","sort":32,"title":"EU and UK data residency","area":"Platform","horizon":"later","status":"Exploring","go":null,"votes":4,"asked_by":[],"refs":["Asana","Cascade","ClickUp"],"why":"Expected by European enterprise and public sector buyers.","what":null,"collab":null,"extra":null},{"id":"RM34","sort":33,"title":"Audit log","area":"Platform","horizon":"done","status":"Shipped","go":"settings-pl-audit","votes":7,"asked_by":["F"],"refs":["Asana","Linear","monday.com"],"why":"Admins need to see who changed what, and when.","what":"Every change is recorded with who, when and what, with search, filters and CSV export.","collab":null,"extra":null},{"id":"RM35","sort":34,"title":"Scheduled email digests","area":"Integrations","horizon":"now","status":"Planned","go":null,"votes":6,"asked_by":["S"],"refs":["ServiceNow SPM","Profit.co","Asana"],"why":"A weekly summary of what changed, sent to leaders who do not log in every day.","what":null,"collab":null,"extra":null},{"id":"RM40","sort":35,"title":"One owner, contributors and followers on every object","area":"Collaboration","horizon":"now","status":"Planned","go":null,"votes":18,"asked_by":["S","P","F"],"refs":["Asana","Linear","WorkBoard","Perdoo"],"why":"Objectives, measures, key results, initiatives, risks and tasks each need one accountable owner, with named contributors who can update and followers who are kept informed.","what":"Adds a RACI view built from those roles, with a warning when an item has no owner or two.","collab":1,"extra":null},{"id":"RM41","sort":36,"title":"Accept, decline or propose a new date","area":"Collaboration","horizon":"now","status":"Planned","go":null,"votes":17,"asked_by":["F","P","S"],"refs":["Linear","Profit.co"],"why":"Work is assigned, but nobody agrees to it. Almost no tool asks for agreement, and strategy owners want it.","what":"Tasks, actions, hand-overs and target requests can be accepted, declined with a reason, or answered with a new date. Committed dates are kept apart from target dates, and requests nobody answers get a nudge.","collab":1,"extra":null},{"id":"RM42","sort":37,"title":"Comment threads on every object","area":"Collaboration","horizon":"now","status":"Planned","go":null,"votes":16,"asked_by":["S","P","F"],"refs":["Linear","Notion","ClickUp","Confluence"],"why":"Today only tasks and status updates can be discussed; decisions, measures, gates, risks and budgets cannot.","what":"Threaded comments with mentions, reactions, resolve and reopen. A comment can be assigned as an action or turned into a decision.","collab":1,"extra":null},{"id":"RM43","sort":38,"title":"Milestones with acceptance and evidence","area":"Portfolio","horizon":"now","status":"Planned","go":null,"votes":14,"asked_by":["P","S"],"refs":["Planview","Wrike","Planisware"],"why":"Milestones are quarters that count as met once the date passes.","what":"Named milestones with an accepter, completion criteria and evidence. A milestone is met only when it is accepted; slips roll up to the initiative and to the key result's confidence.","collab":1,"extra":null},{"id":"RM44","sort":39,"title":"Catchball and target agreement","area":"Strategy","horizon":"now","status":"Planned","go":null,"votes":13,"asked_by":["S"],"refs":["Profit.co","WorkBoard","i-nexus","Perdoo"],"why":"Unit objectives and targets go live at once, with nothing proposed or agreed.","what":"Draft, propose, counter-propose, agree and lock objectives, targets and key results. Alignment requests go to the parent owner; a key result shared across teams has contributions each team accepts.","collab":1,"extra":null},{"id":"RM45","sort":40,"title":"Review meetings that produce owned work","area":"Strategy","horizon":"now","status":"Planned","go":null,"votes":12,"asked_by":["S","P"],"refs":["WorkBoard","Fellow","Confluence"],"why":"Steering actions never reach the owner, and reviews have no agenda, pre-reads or minutes.","what":"Attendees, an agenda drawn from exceptions, a pre-read deadline, minutes, and actions that land in the owner's My work, carry forward until done and give a say/do rate.","collab":1,"extra":null},{"id":"RM46","sort":41,"title":"Resource requests with negotiation","area":"Portfolio","horizon":"next","status":"Planned","go":null,"votes":10,"asked_by":["P"],"refs":["ServiceNow SPM","Planview","Tempus Resource"],"why":"Capacity is a number per role, with no request or confirmation.","what":"Project managers request people by role. Line managers confirm, propose someone else or another time, or decline, moving from soft to hard booking.","collab":1,"extra":null},{"id":"RM47","sort":42,"title":"Absence cover and hand-over","area":"Work","horizon":"next","status":"Planned","go":null,"votes":9,"asked_by":["F","S"],"refs":["monday.com","Asana"],"why":"Work stalls when someone is away, and a change of owner leaves no note.","what":"Out-of-office dates with a named cover, who receives assignments, approvals and check-in reminders while the owner is away. A transfer of ownership comes with a hand-over note.","collab":1,"extra":null},{"id":"RM48","sort":43,"title":"Team triage queues","area":"Work","horizon":"next","status":"Planned","go":null,"votes":8,"asked_by":["F"],"refs":["Linear","Jira","monday.com"],"why":"Small requests have no front door between personal tasks and portfolio requests.","what":"A queue per team with accept, decline, merge and snooze, a rotating triage owner, and round robin that skips people who are away.","collab":1,"extra":null},{"id":"RM49","sort":44,"title":"Committed and stretch targets with say/do","area":"Strategy","horizon":"next","status":"Planned","go":null,"votes":9,"asked_by":["S","F"],"refs":["WorkBoard","Atlassian","Jira","Linear"],"why":"Not every key result is a promise. Leaders want to see who delivers what they commit to.","what":"A committed and a stretch target on each key result. Status uses the committed target. Each owner and team gets a say/do rate per period.","collab":1,"extra":null},{"id":"RM50","sort":45,"title":"An inbox you can act from","area":"Collaboration","horizon":"next","status":"Planned","go":null,"votes":9,"asked_by":["F"],"refs":["Linear","Asana","ClickUp"],"why":"The inbox can only be read and archived.","what":"Reply, accept, approve and snooze from the inbox, with updates bundled per item and quiet hours.","collab":1,"extra":null},{"id":"RM51","sort":46,"title":"Workload you can act on","area":"Work","horizon":"next","status":"Planned","go":null,"votes":8,"asked_by":["F","P"],"refs":["Asana","monday.com","Wrike"],"why":"Overdue work disappears from future weeks, so overload is hidden.","what":"Overdue work carries forward, unassigned work gets its own row, and time off is shown. Drag to reassign, and see a warning when an assignment overloads someone.","collab":1,"extra":null},{"id":"RM52","sort":47,"title":"Done criteria and review before completion","area":"Work","horizon":"next","status":"Planned","go":null,"votes":7,"asked_by":["F","P"],"refs":["Jira","Asana"],"why":"Mark complete asks for nothing, and in some tools a rejected approval still counts as done.","what":"Definitions of done and an optional reviewer on tasks and deliverables. Approvals complete only when someone approves.","collab":1,"extra":null},{"id":"RM53","sort":48,"title":"Agreed baselines and benefit hand-over","area":"Portfolio","horizon":"later","status":"Exploring","go":null,"votes":6,"asked_by":["P"],"refs":["Planview","Broadcom Clarity"],"why":"Baselines are set by the owner alone, and benefits have no owner after closure.","what":"The team agrees the plan and the sponsor signs off the baseline. At closure, benefits are handed to a named operations owner who accepts them.","collab":1,"extra":null},{"id":"RM54","sort":49,"title":"Celebrate finished work","area":"Collaboration","horizon":"later","status":"Exploring","go":null,"votes":5,"asked_by":["F"],"refs":["Asana","Lattice"],"why":"Recognition sits on a strategy page, cut off from the work.","what":"Kudos and celebrations when milestones are accepted, key results are met or initiatives close.","collab":1,"extra":null},{"id":"RM55","sort":50,"title":"Rule builder for automation","area":"Work","horizon":"later","status":"Exploring","go":null,"votes":6,"asked_by":["F"],"refs":["Asana","monday.com","Jira"],"why":"Six fixed rules cannot fit every team.","what":"Build your own rules as When, If and Then, with templates and a run log.","collab":1,"extra":null},{"id":"RM56","sort":51,"title":"Portfolio planning cycle","area":"Portfolio","horizon":"later","status":"Exploring","go":null,"votes":5,"asked_by":["P","S"],"refs":["Shape Up","Planview"],"why":"Choosing what to fund each cycle happens outside the tool.","what":"Run a cycle with candidates, appetite and scores, then decide what to fund or drop.","collab":1,"extra":null},{"id":"RM60","sort":52,"title":"Link accounts to people","area":"Platform","horizon":"now","status":"Planned","go":null,"votes":9,"asked_by":["F"],"refs":["Asana","Linear"],"why":"In a shared workspace, task and check-in history is still credited to the demo person; only the audit log shows the real account.","what":"Each signed-in account is linked to a person, so assignments, comments, check-ins and approvals carry their name.","collab":null,"extra":null},{"id":"RM61","sort":53,"title":"One status model on every strategy page","area":"Strategy","horizon":"now","status":"Planned","go":null,"votes":10,"asked_by":["S"],"refs":["Cascade","ClearPoint"],"why":"OGSM, V2MOM, the X-matrix and the ambition page still keep their own hand-set statuses and baselines, so they can disagree with the scorecard.","what":"Every strategy page reads the same calculated statuses, targets and baselines.","collab":null,"extra":null},{"id":"RM62","sort":54,"title":"Invitation emails","area":"Integrations","horizon":"next","status":"Planned","go":null,"votes":7,"asked_by":["F"],"refs":["Asana","monday.com"],"why":"Invited people must be told by hand to sign in and join.","what":"Send an email with a join link when someone is invited.","collab":null,"extra":null},{"id":"RM63","sort":55,"title":"Approved date changes move dependent work","area":"Portfolio","horizon":"next","status":"Planned","go":null,"votes":6,"asked_by":["P"],"refs":["Microsoft Planner","Smartsheet"],"why":"Approving a later end date lists the dependent initiatives but does not move them.","what":"Offer to move dependent initiatives, or raise a change request for each, when a date change is approved.","collab":null,"extra":null},{"id":"RM64","sort":56,"title":"Capex and opex by month","area":"Portfolio","horizon":"next","status":"Planned","go":null,"votes":5,"asked_by":["P"],"refs":["Broadcom Clarity","Planview"],"why":"The capex share is one figure per initiative.","what":"Split capex and opex month by month in the finance grid.","collab":null,"extra":null},{"id":"RM65","sort":57,"title":"Project and task templates","area":"Work","horizon":"next","status":"Planned","go":null,"votes":8,"asked_by":[],"refs":["Asana","monday.com","Smartsheet"],"why":"Every new initiative or project starts from scratch.","what":"Save an initiative or project as a template with its tasks, phases, gates and roles, and start new work from it.","collab":null,"extra":null},{"id":"RM66","sort":58,"title":"Recurring tasks","area":"Work","horizon":"next","status":"Planned","go":null,"votes":6,"asked_by":[],"refs":["Asana","ClickUp","Wrike"],"why":"Monthly closes, check-ins and reviews have to be added by hand each time.","what":"Tasks that repeat on a schedule.","collab":null,"extra":null},{"id":"RM67","sort":59,"title":"Live demo dates and fresh sample data","area":"Platform","horizon":"next","status":"Planned","go":null,"votes":7,"asked_by":["F"],"refs":[],"why":"The demo is fixed on 16 September 2024; resource data is from 2023 and RAID review dates are in the past.","what":"The demo follows today's date and every sample record is consistent with it.","collab":null,"extra":null},{"id":"RM68","sort":60,"title":"One date format everywhere","area":"Platform","horizon":"next","status":"Planned","go":null,"votes":4,"asked_by":["F"],"refs":[],"why":"Project cards use month-first dates while the rest of the app uses day-first.","what":"Dates follow the user's locale setting everywhere.","collab":null,"extra":null},{"id":"RM69","sort":61,"title":"Dashboard actions and assistant search on live data","area":"Work","horizon":"next","status":"Planned","go":null,"votes":5,"asked_by":[],"refs":[],"why":"The dashboard's Actions widget and the assistant's document search still read fixed sample lists.","what":"Both read the live tasks, actions and records.","collab":null,"extra":null},{"id":"RM70","sort":62,"title":"Dashboard builder","area":"Reporting","horizon":"later","status":"Exploring","go":null,"votes":6,"asked_by":[],"refs":["Asana","monday.com","Smartsheet"],"why":"Dashboards are fixed pages.","what":"Build dashboards from widgets across measures, initiatives, tasks and budgets, and share them.","collab":null,"extra":null},{"id":"RM71","sort":63,"title":"Documents and briefs linked to work","area":"Collaboration","horizon":"later","status":"Exploring","go":null,"votes":5,"asked_by":[],"refs":["Notion","ClickUp","Confluence"],"why":"Business cases and briefs live in files outside the work.","what":"Write briefs, business cases and meeting notes next to the initiative, with inline comments.","collab":null,"extra":null},{"id":"RM72","sort":64,"title":"Guest access for clients and partners","area":"Platform","horizon":"later","status":"Exploring","go":null,"votes":5,"asked_by":["F"],"refs":["Asana","Basecamp","Smartsheet"],"why":"Roles cover your own staff only.","what":"Invite outside guests to chosen initiatives with limited rights.","collab":null,"extra":null},{"id":"RM73","sort":65,"title":"Presence: see who is viewing","area":"Collaboration","horizon":"later","status":"Exploring","go":null,"votes":4,"asked_by":["F"],"refs":["Notion","Linear"],"why":"In a shared workspace you cannot see who else is looking at the same page.","what":"Show who is viewing a page or editing a record, to avoid clashes.","collab":null,"extra":null}]$ribgcog$::jsonb);
